// Number System · Divisibility Rules · Medium #2 - #6. Every answer is worked
// out again in `v`. Each test opens gently and builds up: one missing digit
// and direct rules first, counting in the middle, two unknown digits and
// properties at the end.
const L = require("./lib");
const { fmt } = require("./fmt");
const T = (n) => `Number System · Divisibility Rules · Medium #${n}`;
const num = (s) => Number(String(s).replace(/,/g, ""));
const ok = (o, a, value) => L.only(o, a, value);
const Q = (t, q, qh, o, a, value, s, sh, oh) => ({ t, q, qh, o, ...(oh ? { oh } : {}), a, v: () => ok(o, a, String(value())), s, sh });
const which = (o, test) => () => o.filter((x) => test(num(x))).join(" & ");
const R = L.range;
const fmtN = (n) => Number(n).toLocaleString("en-US");
// Every way of filling the letters of a pattern so that the number is divisible by m.
const fills = (pattern, m) => L.fill(pattern, (n) => n % BigInt(m) === 0n);
const single = (xs) => { const u = [...new Set(xs.map(String))]; return u.length === 1 ? u[0] : `several: ${u.join("/")}`; };
const asNumber = (pattern, e) => Number(pattern.replace(/[a-z]/g, (c) => e[c]));
const distinct = (n) => new Set(String(n)).size === String(n).length;

const list = [
  // ------------------------------------------------------------ MEDIUM #2
  Q(T(2), "If the four-digit number 5a35 is divisible by 7, what is the value of a?", "यदि चार अंकों की संख्या 5a35, 7 से विभाज्य है, तो a का मान क्या है?", ["6", "3", "1", "8"], 0, () => single(fills("5a35", 7).map((e) => e.a)),
    "5a35 = 5035 + 100a. 5035 = 7 × 719 + 2 and 100 leaves 2 on division by 7, so 2 + 2a must be a multiple of 7: a = 6 (5635 = 7 × 805).", "5a35 = 5035 + 100a। 5035 = 7 × 719 + 2 और 100 का 7 से शेष 2, अतः 2 + 2a, 7 का गुणज हो: a = 6 (5635 = 7 × 805)।"),
  Q(T(2), "Which of 2,163, 2,171, 2,183 and 2,197 is divisible by 7?", "2,163, 2,171, 2,183 और 2,197 में से कौन-सी संख्या 7 से विभाज्य है?", ["2,163", "2,171", "2,183", "2,197"], 0, which(["2,163", "2,171", "2,183", "2,197"], (n) => n % 7 === 0),
    "Double the last digit and subtract it from the rest: 216 − 6 = 210 = 7 × 30, so 2,163 is divisible by 7 (2,163 = 7 × 309). For the others: 217 − 2 = 215, 218 − 6 = 212, 219 − 14 = 205 - none a multiple of 7.", "अंतिम अंक का दोगुना शेष में से घटाएँ: 216 − 6 = 210 = 7 × 30, अतः 2,163, 7 से विभाज्य (2,163 = 7 × 309)। अन्य: 217 − 2 = 215, 218 − 6 = 212, 219 − 14 = 205 - कोई 7 का गुणज नहीं।"),
  Q(T(2), "What is the largest four-digit number divisible by 13?", "13 से विभाज्य चार अंकों की सबसे बड़ी संख्या कौन-सी है?", ["9,997", "9,984", "9,999", "9,990"], 0, () => fmtN(R(1000, 9999).filter((n) => n % 13 === 0).pop()),
    "9,999 = 13 × 769 + 2, so subtract 2: 9,997 = 13 × 769.", "9,999 = 13 × 769 + 2, अतः 2 घटाएँ: 9,997 = 13 × 769।"),
  Q(T(2), "What is the least number that must be added to 9,876 to make it divisible by 33?", "9,876 में कम से कम कौन-सी संख्या जोड़ें कि वह 33 से विभाज्य हो जाए?", ["24", "9", "15", "6"], 0, () => (33 - (9876 % 33)) % 33,
    "33 × 299 = 9,867, so 9,876 leaves 9 and needs 33 − 9 = 24 more: 9,900 = 33 × 300.", "33 × 299 = 9,867, अतः 9,876 का शेष 9 और 33 − 9 = 24 और चाहिए: 9,900 = 33 × 300।"),
  Q(T(2), "If the four-digit number 3a42 is divisible by 7, what is the value of a?", "यदि चार अंकों की संख्या 3a42, 7 से विभाज्य है, तो a का मान क्या है?", ["5", "2", "4", "9"], 0, () => single(fills("3a42", 7).map((e) => e.a)),
    "3a42 = 3042 + 100a. 3042 = 7 × 434 + 4 and 100 leaves 2, so 4 + 2a must be a multiple of 7: a = 5 (3542 = 7 × 506).", "3a42 = 3042 + 100a। 3042 = 7 × 434 + 4 और 100 का शेष 2, अतः 4 + 2a, 7 का गुणज हो: a = 5 (3542 = 7 × 506)।"),
  Q(T(2), "Which of 4,824, 5,634, 6,248 and 7,412 is divisible by 24?", "4,824, 5,634, 6,248 और 7,412 में से कौन-सी संख्या 24 से विभाज्य है?", ["4,824", "5,634", "6,248", "7,412"], 0, which(["4,824", "5,634", "6,248", "7,412"], (n) => n % 24 === 0),
    "24 = 8 × 3. Last three digits: 824 = 8 × 103 and 248 = 8 × 31 pass, 634 and 412 do not. Digit sums: 4,824 → 18 (passes 3), 6,248 → 20 (fails). So 4,824 = 24 × 201.", "24 = 8 × 3। अंतिम तीन अंक: 824 = 8 × 103 और 248 = 8 × 31 पार, 634 और 412 नहीं। अंकों के योग: 4,824 → 18 (3 पार), 6,248 → 20 (विफल)। अतः 4,824 = 24 × 201।"),
  Q(T(2), "Which of the following does NOT divide 999,999?", "निम्नलिखित में से कौन 999,999 को विभाजित नहीं करता?", ["17", "37", "13", "27"], 0, () => ["17", "37", "13", "27"].filter((d) => 999999 % num(d) !== 0).join(),
    "999,999 = 999 × 1,001 = 27 × 37 × 7 × 11 × 13. So 37, 13 and 27 divide it; 17 does not.", "999,999 = 999 × 1,001 = 27 × 37 × 7 × 11 × 13। अतः 37, 13 और 27 इसे विभाजित करते हैं; 17 नहीं।"),
  Q(T(2), "How many numbers from 1 to 500 are divisible by 4 but not by 6?", "1 से 500 तक कितनी संख्याएँ 4 से विभाज्य हैं पर 6 से नहीं?", ["84", "125", "83", "42"], 0, () => L.count(1, 500, (n) => n % 4 === 0 && n % 6 !== 0),
    "Multiples of 4: 125. Those also divisible by 6 are the multiples of LCM(4, 6) = 12: 41. So 125 − 41 = 84.", "4 के गुणज: 125। जो 6 से भी विभाज्य हैं वे LCM(4, 6) = 12 के गुणज: 41। अतः 125 − 41 = 84।"),
  Q(T(2), "How many numbers from 1 to 1,000 are divisible by at least one of 3, 4 and 5?", "1 से 1,000 तक कितनी संख्याएँ 3, 4 और 5 में से कम से कम एक से विभाज्य हैं?", ["600", "783", "533", "400"], 0, () => L.count(1, 1000, (n) => n % 3 === 0 || n % 4 === 0 || n % 5 === 0),
    "By inclusion-exclusion: 333 + 250 + 200 − (83 + 66 + 50) + 16 = 783 − 199 + 16 = 600. (83, 66, 50 count multiples of 12, 15, 20; 16 counts multiples of 60.)", "समावेशन-अपवर्जन से: 333 + 250 + 200 − (83 + 66 + 50) + 16 = 783 − 199 + 16 = 600। (83, 66, 50 क्रमशः 12, 15, 20 के गुणज; 16, 60 के गुणज।)"),
  Q(T(2), "How many numbers from 1 to 300 are divisible by none of 2, 3 and 5?", "1 से 300 तक कितनी संख्याएँ 2, 3 और 5 में से किसी से भी विभाज्य नहीं हैं?", ["80", "220", "90", "70"], 0, () => L.count(1, 300, (n) => n % 2 && n % 3 && n % 5),
    "Divisible by at least one: 150 + 100 + 60 − (50 + 30 + 20) + 10 = 220. So 300 − 220 = 80 are divisible by none.", "कम से कम एक से विभाज्य: 150 + 100 + 60 − (50 + 30 + 20) + 10 = 220। अतः 300 − 220 = 80 किसी से विभाज्य नहीं।"),
  Q(T(2), "How many three-digit numbers with all digits different can be formed from the digits 0, 1, 2, 3, 4 and 5 that are divisible by 5?", "अंकों 0, 1, 2, 3, 4 और 5 से भिन्न अंकों वाली तीन अंकों की कितनी संख्याएँ बन सकती हैं जो 5 से विभाज्य हों?", ["36", "40", "20", "48"], 0, () => L.count(100, 999, (n) => distinct(n) && [...String(n)].every((c) => "012345".includes(c)) && n % 5 === 0),
    "The last digit is 0 or 5. Ending in 0: 5 × 4 = 20 ways for the first two digits. Ending in 5: the first digit cannot be 0 or 5 (4 ways), the middle any of the remaining 4: 16. Total 20 + 16 = 36.", "अंतिम अंक 0 या 5। 0 पर: पहले दो अंक 5 × 4 = 20 तरह। 5 पर: पहला अंक 0 या 5 नहीं (4 तरह), बीच का बचे 4 में से कोई: 16। कुल 20 + 16 = 36।"),
  Q(T(2), "How many four-digit numbers of the form 4ab8 are divisible by 8?", "4ab8 रूप की चार अंकों की कितनी संख्याएँ 8 से विभाज्य हैं?", ["25", "20", "30", "50"], 0, () => fills("4ab8", 8).length,
    "Only ab8 matters: 100a + 10b + 8 leaves 4a + 2b on division by 8, so 2a + b must be a multiple of 4. For each a, b runs over 0-9 and exactly 2 or 3 values fit; counting all a gives 25.", "केवल ab8 मायने रखता है: 100a + 10b + 8 का 8 से शेष 4a + 2b जैसा, अतः 2a + b, 4 का गुणज हो। हर a के लिए b (0-9) के 2 या 3 मान बनते हैं; सभी a गिनने पर 25।"),
  Q(T(2), "What is the smallest five-digit number divisible by each of 7, 11 and 13?", "7, 11 और 13 में से प्रत्येक से विभाज्य पाँच अंकों की सबसे छोटी संख्या कौन-सी है?", ["10,010", "10,001", "11,011", "10,101"], 0, () => fmtN(R(10000, 99999).find((n) => n % 1001 === 0)),
    "Divisible by 7, 11 and 13 means divisible by 7 × 11 × 13 = 1,001. The multiples are 1,001, 2,002, ...; the first with five digits is 1,001 × 10 = 10,010.", "7, 11 और 13 से विभाज्य यानी 7 × 11 × 13 = 1,001 से विभाज्य। गुणज 1,001, 2,002, ...; पाँच अंकों वाला पहला 1,001 × 10 = 10,010।"),
  Q(T(2), "What is the least natural number n for which 3ⁿ − 1 is divisible by 13?", "वह न्यूनतम प्राकृत संख्या n कौन-सी है जिसके लिए 3ⁿ − 1, 13 से विभाज्य है?", ["3", "4", "6", "12"], 0, () => R(1, 20).find((n) => (3 ** n - 1) % 13 === 0),
    "3¹ − 1 = 2, 3² − 1 = 8, 3³ − 1 = 26 = 13 × 2. So n = 3.", "3¹ − 1 = 2, 3² − 1 = 8, 3³ − 1 = 26 = 13 × 2। अतः n = 3।"),
  Q(T(2), "A three-digit number minus the number formed by reversing its digits (abc − cba) is always divisible by:", "तीन अंकों की संख्या में से उसके अंक उलटकर बनी संख्या घटाने पर (abc − cba) परिणाम सदैव किससे विभाज्य होता है?", ["99", "101", "111", "18"], 0, () => ["99", "101", "111", "18"].filter((d) => R(100, 999).every((n) => (n - Number([...String(n)].reverse().join(""))) % num(d) === 0)).join(),
    "abc − cba = (100a + 10b + c) − (100c + 10b + a) = 99(a − c), always a multiple of 99. It need not be a multiple of 18: 413 − 314 = 99.", "abc − cba = (100a + 10b + c) − (100c + 10b + a) = 99(a − c), सदैव 99 का गुणज। 18 का गुणज आवश्यक नहीं: 413 − 314 = 99।"),
  Q(T(2), "A four-digit number of the form abab (such as 3737) is always divisible by:", "abab रूप की चार अंकों की संख्या (जैसे 3737) सदैव किससे विभाज्य होती है?", ["101", "11", "111", "1001"], 0, () => ["101", "11", "111", "1001"].filter((d) => R(10, 99).every((ab) => (ab * 101) % num(d) === 0)).join(),
    "abab = ab × 100 + ab = ab × 101, so it is always a multiple of 101. 3737 = 37 × 101 is not divisible by 11, 111 or 1001.", "abab = ab × 100 + ab = ab × 101, अतः सदैव 101 का गुणज। 3737 = 37 × 101, 11, 111 या 1001 से विभाज्य नहीं।"),
  Q(T(2), "The six numbers formed by arranging the digits 1, 2 and 3 (each used once) are added. The sum is divisible by:", "अंकों 1, 2 और 3 (हर एक एक बार) को व्यवस्थित करके बनी छह संख्याओं को जोड़ा जाता है। योग किससे विभाज्य है?", ["37", "17", "19", "23"], 0, () => ["37", "17", "19", "23"].filter((d) => [123, 132, 213, 231, 312, 321].reduce((a, b) => a + b, 0) % num(d) === 0).join(),
    "Each digit appears twice in each place, so the sum is 2 × (1 + 2 + 3) × 111 = 1,332 = 37 × 36. It is divisible by 37 but not by 17, 19 or 23.", "हर अंक हर स्थान पर दो बार आता है, अतः योग = 2 × (1 + 2 + 3) × 111 = 1,332 = 37 × 36। यह 37 से विभाज्य है, 17, 19 या 23 से नहीं।"),
  Q(T(2), "If the five-digit number 6a92b is divisible by 88, what is the value of a + b?", "यदि पाँच अंकों की संख्या 6a92b, 88 से विभाज्य है, तो a + b का मान क्या है?", ["2", "8", "10", "6"], 0, () => single(fills("6a92b", 88).map((e) => e.a + e.b)),
    "88 = 8 × 11. For 8: 92b is a multiple of 8 only for b = 0 (920 = 8 × 115). For 11: (6 + 9 + 0) − (a + 2) = 13 − a must be a multiple of 11, so a = 2. a + b = 2 (62,920 = 88 × 715).", "88 = 8 × 11। 8 के लिए: 92b केवल b = 0 पर 8 का गुणज (920 = 8 × 115)। 11 के लिए: (6 + 9 + 0) − (a + 2) = 13 − a, 11 का गुणज हो, अतः a = 2। a + b = 2 (62,920 = 88 × 715)।"),
  Q(T(2), "If the five-digit number 7a5b8 is divisible by 72, what is the value of a + b?", "यदि पाँच अंकों की संख्या 7a5b8, 72 से विभाज्य है, तो a + b का मान क्या है?", ["7", "8", "6", "9"], 0, () => single(fills("7a5b8", 72).map((e) => e.a + e.b)),
    "72 = 8 × 9. For 9: 7 + a + 5 + b + 8 = 20 + a + b must be a multiple of 9, so a + b = 7 or 16. For 8: 5b8 must be a multiple of 8, which gives b = 2 or 6. With b = 2, a = 5; with b = 6, a = 1; a + b = 16 would need a = 14 or 10. Either way a + b = 7.", "72 = 8 × 9। 9 के लिए: 7 + a + 5 + b + 8 = 20 + a + b, 9 का गुणज, अतः a + b = 7 या 16। 8 के लिए: 5b8, 8 का गुणज, जिससे b = 2 या 6। b = 2 पर a = 5; b = 6 पर a = 1; a + b = 16 के लिए a = 14 या 10 चाहिए। हर हाल में a + b = 7।"),
  Q(T(2), "If the five-digit number 2a48b is divisible by 88, what is the largest possible value of a + b?", "यदि पाँच अंकों की संख्या 2a48b, 88 से विभाज्य है, तो a + b का सबसे बड़ा संभव मान क्या है?", ["14", "9", "17", "12"], 0, () => Math.max(...fills("2a48b", 88).map((e) => e.a + e.b)),
    "For 8: 48b is a multiple of 8 for b = 0 or 8 (480, 488). For 11: (2 + 4 + b) − (a + 8) = b − a − 2 must be 0 or a multiple of 11. b = 0 gives a = 9; b = 8 gives a = 6. So a + b is 9 or 14; the largest is 14 (26,488 = 88 × 301).", "8 के लिए: 48b, b = 0 या 8 पर 8 का गुणज (480, 488)। 11 के लिए: (2 + 4 + b) − (a + 8) = b − a − 2, 0 या 11 का गुणज हो। b = 0 पर a = 9; b = 8 पर a = 6। अतः a + b = 9 या 14; सबसे बड़ा 14 (26,488 = 88 × 301)।"),

  // ------------------------------------------------------------ MEDIUM #3
  Q(T(3), "If the four-digit number 6a19 is divisible by 13, what is the value of a?", "यदि चार अंकों की संख्या 6a19, 13 से विभाज्य है, तो a का मान क्या है?", ["0", "3", "6", "9"], 0, () => single(fills("6a19", 13).map((e) => e.a)),
    "6a19 = 6019 + 100a. 6019 = 13 × 463 exactly, and 100a must then be a multiple of 13 too; since 13 does not divide 100, a = 0.", "6a19 = 6019 + 100a। 6019 = 13 × 463 ठीक-ठीक, अतः 100a भी 13 का गुणज हो; 13, 100 को विभाजित नहीं करता, अतः a = 0।"),
  Q(T(3), "If the four-digit number 7a13 is divisible by 13, what is the value of a?", "यदि चार अंकों की संख्या 7a13, 13 से विभाज्य है, तो a का मान क्या है?", ["8", "2", "5", "6"], 0, () => single(fills("7a13", 13).map((e) => e.a)),
    "7a13 = 7013 + 100a. 7013 = 13 × 539 + 6 and 100 leaves 9, so 6 + 9a must be a multiple of 13. a = 8 gives 78 = 13 × 6. So a = 8 (7813 = 13 × 601).", "7a13 = 7013 + 100a। 7013 = 13 × 539 + 6 और 100 का शेष 9, अतः 6 + 9a, 13 का गुणज हो। a = 8 पर 78 = 13 × 6। अतः a = 8 (7813 = 13 × 601)।"),
  Q(T(3), "The four-digit number 42a8 is divisible by 7. What is the sum of all possible values of the digit a?", "चार अंकों की संख्या 42a8, 7 से विभाज्य है। अंक a के सभी संभव मानों का योग क्या है?", ["11", "9", "2", "7"], 0, () => fills("42a8", 7).reduce((s, e) => s + e.a, 0),
    "42a8 = 4208 + 10a. 4208 = 7 × 601 + 1 and 10 leaves 3, so 1 + 3a must be a multiple of 7: a = 2 (7) or a = 9 (28). The sum is 2 + 9 = 11.", "42a8 = 4208 + 10a। 4208 = 7 × 601 + 1 और 10 का शेष 3, अतः 1 + 3a, 7 का गुणज हो: a = 2 (7) या a = 9 (28)। योग 2 + 9 = 11।"),
  Q(T(3), "What is the smallest four-digit number divisible by each of 12, 15 and 18?", "12, 15 और 18 में से प्रत्येक से विभाज्य चार अंकों की सबसे छोटी संख्या कौन-सी है?", ["1,080", "1,020", "1,260", "1,140"], 0, () => fmtN(R(1000, 9999).find((n) => n % L.lcm(12, 15, 18) === 0)),
    "LCM(12, 15, 18) = 180. 1,000 = 180 × 5 + 100, so the next multiple is 180 × 6 = 1,080.", "LCM(12, 15, 18) = 180। 1,000 = 180 × 5 + 100, अतः अगला गुणज 180 × 6 = 1,080।"),
  Q(T(3), "What is the largest three-digit number divisible by each of 6, 8 and 12?", "6, 8 और 12 में से प्रत्येक से विभाज्य तीन अंकों की सबसे बड़ी संख्या कौन-सी है?", ["984", "996", "960", "972"], 0, () => R(100, 999).filter((n) => n % L.lcm(6, 8, 12) === 0).pop(),
    "LCM(6, 8, 12) = 24. 999 = 24 × 41 + 15, so the largest multiple is 999 − 15 = 984.", "LCM(6, 8, 12) = 24। 999 = 24 × 41 + 15, अतः सबसे बड़ा गुणज 999 − 15 = 984।"),
  Q(T(3), "How many numbers from 1 to 100 are divisible by exactly one of 2 and 3?", "1 से 100 तक कितनी संख्याएँ 2 और 3 में से ठीक एक से विभाज्य हैं?", ["51", "67", "33", "16"], 0, () => L.count(1, 100, (n) => (n % 2 === 0) !== (n % 3 === 0)),
    "Multiples of 2: 50; of 3: 33; of both (6): 16. Exactly one: (50 − 16) + (33 − 16) = 34 + 17 = 51.", "2 के गुणज: 50; 3 के: 33; दोनों (6) के: 16। ठीक एक: (50 − 16) + (33 − 16) = 34 + 17 = 51।"),
  Q(T(3), "How many three-digit numbers are divisible by 7 or by 11?", "तीन अंकों की कितनी संख्याएँ 7 या 11 से विभाज्य हैं?", ["198", "210", "128", "81"], 0, () => L.count(100, 999, (n) => n % 7 === 0 || n % 11 === 0),
    "Three-digit multiples of 7: 105 to 994, i.e. 128. Of 11: 110 to 990, i.e. 81. Of 77: 154 to 924, i.e. 11. So 128 + 81 − 11 = 198.", "7 के तीन अंकों के गुणज: 105 से 994, यानी 128। 11 के: 110 से 990, यानी 81। 77 के: 154 से 924, यानी 11। अतः 128 + 81 − 11 = 198।"),
  Q(T(3), "How many numbers from 1 to 2,000 are divisible by 12 but not by 18?", "1 से 2,000 तक कितनी संख्याएँ 12 से विभाज्य हैं पर 18 से नहीं?", ["111", "166", "55", "112"], 0, () => L.count(1, 2000, (n) => n % 12 === 0 && n % 18 !== 0),
    "Multiples of 12: 166. Those also divisible by 18 are multiples of LCM(12, 18) = 36: 55. So 166 − 55 = 111.", "12 के गुणज: 166। जो 18 से भी विभाज्य हैं वे LCM(12, 18) = 36 के गुणज: 55। अतः 166 − 55 = 111।"),
  Q(T(3), "How many three-digit numbers are divisible by 6 or by 15?", "तीन अंकों की कितनी संख्याएँ 6 या 15 से विभाज्य हैं?", ["180", "210", "150", "60"], 0, () => L.count(100, 999, (n) => n % 6 === 0 || n % 15 === 0),
    "Three-digit multiples of 6: 150; of 15: 60; of LCM(6, 15) = 30: 30. So 150 + 60 − 30 = 180.", "6 के तीन अंकों के गुणज: 150; 15 के: 60; LCM(6, 15) = 30 के: 30। अतः 150 + 60 − 30 = 180।"),
  Q(T(3), "How many three-digit numbers with all digits different can be formed from the digits 1, 2, 3, 4 and 5 that are divisible by 3?", "अंकों 1, 2, 3, 4 और 5 से भिन्न अंकों वाली तीन अंकों की कितनी संख्याएँ बन सकती हैं जो 3 से विभाज्य हों?", ["24", "20", "18", "30"], 0, () => L.count(100, 999, (n) => distinct(n) && [...String(n)].every((c) => "12345".includes(c)) && n % 3 === 0),
    "The three digits must add to a multiple of 3. The sets that do: {1, 2, 3}, {1, 3, 5}, {2, 3, 4} and {3, 4, 5}. Each can be arranged in 3! = 6 ways: 4 × 6 = 24.", "तीन अंकों का योग 3 का गुणज हो। ऐसे समूह: {1, 2, 3}, {1, 3, 5}, {2, 3, 4} और {3, 4, 5}। हर एक 3! = 6 तरह से: 4 × 6 = 24।"),
  Q(T(3), "What is the smallest n for which n! is divisible by 1,000?", "वह सबसे छोटा n कौन-सा है जिसके लिए n!, 1,000 से विभाज्य है?", ["15", "10", "20", "25"], 0, () => R(1, 40).find((n) => L.fact(n) % 1000n === 0n),
    "1,000 = 2³ × 5³, and twos are plentiful, so n! needs three factors of 5. They come from 5, 10 and 15, so the smallest n is 15.", "1,000 = 2³ × 5³, और 2 बहुत हैं, अतः n! में 5 के तीन गुणनखंड चाहिए। ये 5, 10 और 15 से आते हैं, अतः सबसे छोटा n = 15।"),
  Q(T(3), "What is the smallest n for which n! is divisible by 49?", "वह सबसे छोटा n कौन-सा है जिसके लिए n!, 49 से विभाज्य है?", ["14", "7", "49", "21"], 0, () => R(1, 60).find((n) => L.fact(n) % 49n === 0n),
    "49 = 7², so n! needs two factors of 7. They come from 7 and 14, so the smallest n is 14.", "49 = 7², अतः n! में 7 के दो गुणनखंड चाहिए। ये 7 और 14 से आते हैं, अतः सबसे छोटा n = 14।"),
  Q(T(3), "What is the least natural number n for which 2ⁿ + 1 is divisible by 11?", "वह न्यूनतम प्राकृत संख्या n कौन-सी है जिसके लिए 2ⁿ + 1, 11 से विभाज्य है?", ["5", "10", "3", "4"], 0, () => R(1, 20).find((n) => (2 ** n + 1) % 11 === 0),
    "2ⁿ + 1 for n = 1, 2, 3, 4, 5: 3, 5, 9, 17, 33. 33 = 11 × 3, so n = 5.", "n = 1, 2, 3, 4, 5 पर 2ⁿ + 1: 3, 5, 9, 17, 33। 33 = 11 × 3, अतः n = 5।"),
  Q(T(3), "If the four-digit number 5a1b is divisible by 44, what is the value of a + b?", "यदि चार अंकों की संख्या 5a1b, 44 से विभाज्य है, तो a + b का मान क्या है?", ["6", "4", "8", "2"], 0, () => single(fills("5a1b", 44).map((e) => e.a + e.b)),
    "44 = 4 × 11. For 4: 1b is a multiple of 4, so b = 2 or 6. For 11: (5 + 1) − (a + b) must be 0 or 11, so a + b = 6 (b = 2, a = 4 or b = 6, a = 0). Either way a + b = 6.", "44 = 4 × 11। 4 के लिए: 1b, 4 का गुणज, अतः b = 2 या 6। 11 के लिए: (5 + 1) − (a + b), 0 या 11 हो, अतः a + b = 6 (b = 2, a = 4 या b = 6, a = 0)। हर हाल में a + b = 6।"),
  Q(T(3), "If the four-digit number 2a7b is divisible by 55, what is the value of a + b?", "यदि चार अंकों की संख्या 2a7b, 55 से विभाज्य है, तो a + b का मान क्या है?", ["9", "5", "7", "11"], 0, () => single(fills("2a7b", 55).map((e) => e.a + e.b)),
    "55 = 5 × 11. For 5: b = 0 or 5. For 11: (2 + 7) − (a + b) = 9 − (a + b) must be 0 or a multiple of 11, so a + b = 9 (b = 0, a = 9 or b = 5, a = 4).", "55 = 5 × 11। 5 के लिए: b = 0 या 5। 11 के लिए: (2 + 7) − (a + b) = 9 − (a + b), 0 या 11 का गुणज, अतः a + b = 9 (b = 0, a = 9 या b = 5, a = 4)।"),
  Q(T(3), "If the four-digit number 8a3b is divisible by 45, what is the largest possible value of a?", "यदि चार अंकों की संख्या 8a3b, 45 से विभाज्य है, तो a का सबसे बड़ा संभव मान क्या है?", ["7", "2", "5", "9"], 0, () => Math.max(...fills("8a3b", 45).map((e) => e.a)),
    "45 = 5 × 9. For 5: b = 0 or 5. For 9: 8 + a + 3 + b = 11 + a + b is a multiple of 9. b = 0 gives a = 7; b = 5 gives a = 2. The largest a is 7 (8730 = 45 × 194).", "45 = 5 × 9। 5 के लिए: b = 0 या 5। 9 के लिए: 8 + a + 3 + b = 11 + a + b, 9 का गुणज। b = 0 पर a = 7; b = 5 पर a = 2। सबसे बड़ा a = 7 (8730 = 45 × 194)।"),
  Q(T(3), "For how many pairs of digits (a, b) is the four-digit number 7a8b divisible by 15?", "अंकों (a, b) के कितने जोड़ों के लिए चार अंकों की संख्या 7a8b, 15 से विभाज्य है?", ["7", "6", "8", "10"], 0, () => fills("7a8b", 15).length,
    "For 5: b = 0 or 5. For 3: 7 + a + 8 + b = 15 + a + b, so a + b is a multiple of 3. b = 0: a = 0, 3, 6, 9 (4 pairs). b = 5: a = 1, 4, 7 (3 pairs). Total 7.", "5 के लिए: b = 0 या 5। 3 के लिए: 7 + a + 8 + b = 15 + a + b, अतः a + b, 3 का गुणज। b = 0: a = 0, 3, 6, 9 (4 जोड़े)। b = 5: a = 1, 4, 7 (3 जोड़े)। कुल 7।"),
  Q(T(3), "If the five-digit number 53a6b is divisible by 99, what is the value of a + b?", "यदि पाँच अंकों की संख्या 53a6b, 99 से विभाज्य है, तो a + b का मान क्या है?", ["4", "13", "9", "2"], 0, () => single(fills("53a6b", 99).map((e) => e.a + e.b)),
    "For 9: 5 + 3 + a + 6 + b = 14 + a + b, so a + b = 4 or 13. For 11: (5 + a + b) − (3 + 6) = a + b − 4 must be 0 or ±11, so a + b = 4 (15 would be needed for +11). Both tests give a + b = 4.", "9 के लिए: 5 + 3 + a + 6 + b = 14 + a + b, अतः a + b = 4 या 13। 11 के लिए: (5 + a + b) − (3 + 6) = a + b − 4, 0 या ±11, अतः a + b = 4 (+11 के लिए 15 चाहिए)। दोनों जाँचें a + b = 4 देती हैं।"),
  Q(T(3), "The four-digit number a7b6 is divisible by 72. What is the smallest such number?", "चार अंकों की संख्या a7b6, 72 से विभाज्य है। ऐसी सबसे छोटी संख्या कौन-सी है?", ["2,736", "7,776", "1,746", "3,726"], 0, () => fmtN(Math.min(...fills("a7b6", 72).map((e) => asNumber("a7b6", e)))),
    "For 8: 7b6 is a multiple of 8 for b = 3 (736) or b = 7 (776). For 9: a + 7 + b + 6 is a multiple of 9: with b = 3, a = 2; with b = 7, a = 7. The numbers are 2,736 and 7,776; the smaller is 2,736 = 72 × 38.", "8 के लिए: 7b6, b = 3 (736) या b = 7 (776) पर 8 का गुणज। 9 के लिए: a + 7 + b + 6, 9 का गुणज: b = 3 पर a = 2; b = 7 पर a = 7। संख्याएँ 2,736 और 7,776; छोटी 2,736 = 72 × 38।"),
  Q(T(3), "For how many pairs of digits (a, b) is the five-digit number 3a6b2 divisible by 72?", "अंकों (a, b) के कितने जोड़ों के लिए पाँच अंकों की संख्या 3a6b2, 72 से विभाज्य है?", ["3", "2", "4", "1"], 0, () => fills("3a6b2", 72).length,
    "For 8: 6b2 is a multiple of 8 for b = 3 (632) or b = 7 (672). For 9: 3 + a + 6 + b + 2 = 11 + a + b. With b = 3, a = 4 (sum 18); with b = 7, a = 0 or 9 (sums 18, 27). Three pairs.", "8 के लिए: 6b2, b = 3 (632) या b = 7 (672) पर 8 का गुणज। 9 के लिए: 3 + a + 6 + b + 2 = 11 + a + b। b = 3 पर a = 4 (योग 18); b = 7 पर a = 0 या 9 (योग 18, 27)। तीन जोड़े।"),

  // ------------------------------------------------------------ MEDIUM #4
  Q(T(4), "If the four-digit number 8a54 is divisible by 7, what is the value of a?", "यदि चार अंकों की संख्या 8a54, 7 से विभाज्य है, तो a का मान क्या है?", ["5", "2", "3", "9"], 0, () => single(fills("8a54", 7).map((e) => e.a)),
    "8a54 = 8054 + 100a. 8054 = 7 × 1,150 + 4 and 100 leaves 2, so 4 + 2a must be a multiple of 7: a = 5 (8554 = 7 × 1,222).", "8a54 = 8054 + 100a। 8054 = 7 × 1,150 + 4 और 100 का शेष 2, अतः 4 + 2a, 7 का गुणज हो: a = 5 (8554 = 7 × 1,222)।"),
  Q(T(4), "Which of 3,502, 4,501, 5,503 and 6,505 is divisible by 7?", "3,502, 4,501, 5,503 और 6,505 में से कौन-सी संख्या 7 से विभाज्य है?", ["4,501", "3,502", "5,503", "6,505"], 0, which(["4,501", "3,502", "5,503", "6,505"], (n) => n % 7 === 0),
    "4,501 = 7 × 643. The others: 3,502 = 7 × 500 + 2, 5,503 = 7 × 786 + 1, 6,505 = 7 × 929 + 2. So 4,501.", "4,501 = 7 × 643। अन्य: 3,502 = 7 × 500 + 2, 5,503 = 7 × 786 + 1, 6,505 = 7 × 929 + 2। अतः 4,501।"),
  Q(T(4), "Which of 5,331, 6,331, 7,331 and 8,331 is divisible by 13?", "5,331, 6,331, 7,331 और 8,331 में से कौन-सी संख्या 13 से विभाज्य है?", ["6,331", "5,331", "7,331", "8,331"], 0, which(["6,331", "5,331", "7,331", "8,331"], (n) => n % 13 === 0),
    "6,331 = 13 × 487. The numbers differ by 1,000, which leaves 12 on division by 13, so the others leave 1, 12 and 11: only 6,331 is a multiple.", "6,331 = 13 × 487। संख्याओं में 1,000 का अंतर है, जिसका 13 से शेष 12, अतः अन्य 1, 12 और 11 शेष छोड़ती हैं: केवल 6,331 गुणज है।"),
  Q(T(4), "Which of the following divides 1! + 2! + 3! + ... + 10! = 4,037,913?", "निम्नलिखित में से कौन 1! + 2! + 3! + ... + 10! = 4,037,913 को विभाजित करता है?", ["9", "4", "5", "7"], 0, () => ["9", "4", "5", "7"].filter((d) => 4037913 % num(d) === 0).join(),
    "Digit sum 4 + 0 + 3 + 7 + 9 + 1 + 3 = 27, so it is divisible by 9. It is odd, so not by 4; it ends in 3, so not by 5; 4,037,913 = 7 × 576,844 + 5, so not by 7.", "अंकों का योग 4 + 0 + 3 + 7 + 9 + 1 + 3 = 27, अतः 9 से विभाज्य। विषम है, अतः 4 से नहीं; 3 पर समाप्त, अतः 5 से नहीं; 4,037,913 = 7 × 576,844 + 5, अतः 7 से नहीं।"),
  Q(T(4), "What is the largest four-digit number with all digits different that is divisible by 5?", "भिन्न अंकों वाली चार अंकों की वह सबसे बड़ी संख्या कौन-सी है जो 5 से विभाज्य हो?", ["9,875", "9,870", "9,885", "9,865"], 0, () => fmtN(R(1000, 9999).filter((n) => distinct(n) && n % 5 === 0).pop()),
    "Try to keep 9, 8, 7 in front. Ending in 0 gives at most 9,870; ending in 5 gives 9,875, which is larger and has all digits different. (9,885 repeats 8.)", "आगे 9, 8, 7 रखें। 0 पर समाप्त अधिकतम 9,870; 5 पर समाप्त 9,875, जो बड़ी है और सभी अंक भिन्न। (9,885 में 8 दोहराया है।)"),
  Q(T(4), "What is the smallest four-digit number with all digits different that is divisible by 9?", "भिन्न अंकों वाली चार अंकों की वह सबसे छोटी संख्या कौन-सी है जो 9 से विभाज्य हो?", ["1,026", "1,008", "1,035", "1,017"], 0, () => fmtN(R(1000, 9999).find((n) => distinct(n) && n % 9 === 0)),
    "Start with 10__: the last two digits must be different from 1 and 0 and from each other, with 1 + 0 + c + d a multiple of 9, so c + d = 8 or 17. The smallest choice is 2 and 6: 1,026. (1,008 repeats 0; 1,017 repeats 1.)", "10__ से शुरू करें: अंतिम दो अंक 1, 0 और आपस में भिन्न, तथा 1 + 0 + c + d, 9 का गुणज, अतः c + d = 8 या 17। सबसे छोटा चयन 2 और 6: 1,026। (1,008 में 0 दोहराया; 1,017 में 1।)"),
  Q(T(4), "How many two-digit numbers are divisible by the sum of their own digits?", "दो अंकों की कितनी संख्याएँ अपने ही अंकों के योग से विभाज्य हैं?", ["23", "20", "18", "27"], 0, () => L.count(10, 99, (n) => n % L.digitSum(n) === 0),
    "Going through the tens: 10, 12, 18; 20, 21, 24, 27; 30, 36; 40, 42, 45, 48; 50, 54; 60, 63; 70, 72; 80, 81, 84; 90. That is 3 + 4 + 2 + 4 + 2 + 2 + 2 + 3 + 1 = 23.", "दहाइयों के अनुसार: 10, 12, 18; 20, 21, 24, 27; 30, 36; 40, 42, 45, 48; 50, 54; 60, 63; 70, 72; 80, 81, 84; 90। कुल 3 + 4 + 2 + 4 + 2 + 2 + 2 + 3 + 1 = 23।"),
  Q(T(4), "How many three-digit numbers have a digit sum of 9 and are divisible by 5?", "तीन अंकों की कितनी संख्याओं के अंकों का योग 9 है और वे 5 से विभाज्य हैं?", ["13", "9", "15", "10"], 0, () => L.count(100, 999, (n) => L.digitSum(n) === 9 && n % 5 === 0),
    "Ending in 0: the first two digits add to 9 with the first non-zero: 9 numbers (180, 270, ..., 900). Ending in 5: they add to 4: 4 numbers (405, 315, 225, 135). Total 13.", "0 पर समाप्त: पहले दो अंकों का योग 9, पहला शून्येतर: 9 संख्याएँ (180, 270, ..., 900)। 5 पर समाप्त: योग 4: 4 संख्याएँ (405, 315, 225, 135)। कुल 13।"),
  Q(T(4), "How many numbers from 1 to 500 are divisible by exactly two of 2, 3 and 5?", "1 से 500 तक कितनी संख्याएँ 2, 3 और 5 में से ठीक दो से विभाज्य हैं?", ["118", "134", "100", "16"], 0, () => L.count(1, 500, (n) => [2, 3, 5].filter((d) => n % d === 0).length === 2),
    "Multiples of 6, 10 and 15 up to 500: 83, 50 and 33. Each count includes the multiples of 30 (16), which are divisible by all three. So (83 − 16) + (50 − 16) + (33 − 16) = 67 + 34 + 17 = 118.", "500 तक 6, 10 और 15 के गुणज: 83, 50 और 33। हर गिनती में 30 के गुणज (16) हैं, जो तीनों से विभाज्य हैं। अतः (83 − 16) + (50 − 16) + (33 − 16) = 67 + 34 + 17 = 118।"),
  Q(T(4), "What is the sum of all numbers from 1 to 100 that are divisible by 6?", "1 से 100 तक की उन सभी संख्याओं का योग क्या है जो 6 से विभाज्य हैं?", ["816", "750", "900", "786"], 0, () => R(1, 100).filter((n) => n % 6 === 0).reduce((a, b) => a + b, 0),
    "They are 6, 12, ..., 96 = 6 × (1 + 2 + ... + 16) = 6 × 136 = 816.", "ये 6, 12, ..., 96 = 6 × (1 + 2 + ... + 16) = 6 × 136 = 816।"),
  Q(T(4), "For every natural number n, 7ⁿ − 1 is divisible by:", "हर प्राकृत संख्या n के लिए 7ⁿ − 1 किससे विभाज्य है?", ["6", "12", "7", "4"], 0, () => ["6", "12", "7", "4"].filter((d) => R(1, 12).every((n) => (7 ** n - 1) % num(d) === 0)).join(),
    "aⁿ − 1 is always divisible by a − 1, so 7ⁿ − 1 is divisible by 6. For n = 1 it is 6 itself, which 12, 7 and 4 do not divide.", "aⁿ − 1 सदैव a − 1 से विभाज्य है, अतः 7ⁿ − 1, 6 से विभाज्य। n = 1 पर यह स्वयं 6 है, जिसे 12, 7 और 4 विभाजित नहीं करते।"),
  Q(T(4), "For every natural number n, n³ + 5n is divisible by:", "हर प्राकृत संख्या n के लिए n³ + 5n किससे विभाज्य है?", ["6", "12", "5", "10"], 0, () => ["6", "12", "5", "10"].filter((d) => R(1, 40).every((n) => (n ** 3 + 5 * n) % num(d) === 0)).join(),
    "n³ + 5n = (n³ − n) + 6n = (n − 1)n(n + 1) + 6n. The product of three consecutive numbers is divisible by 6, and so is 6n. For n = 1 the value is 6, so nothing larger always works.", "n³ + 5n = (n³ − n) + 6n = (n − 1)n(n + 1) + 6n। तीन क्रमागत संख्याओं का गुणनफल 6 से विभाज्य, और 6n भी। n = 1 पर मान 6, अतः इससे बड़ा कुछ सदैव नहीं।"),
  Q(T(4), "If the four-digit number 6a5b is divisible by 36, what is the value of a + b?", "यदि चार अंकों की संख्या 6a5b, 36 से विभाज्य है, तो a + b का मान क्या है?", ["7", "16", "9", "6"], 0, () => single(fills("6a5b", 36).map((e) => e.a + e.b)),
    "36 = 4 × 9. For 4: 5b is a multiple of 4, so b = 2 or 6. For 9: 6 + a + 5 + b = 11 + a + b, so a + b = 7 or 16; b = 2 gives a = 5 and b = 6 gives a = 1 (a + b = 16 is impossible with these b). So a + b = 7.", "36 = 4 × 9। 4 के लिए: 5b, 4 का गुणज, अतः b = 2 या 6। 9 के लिए: 6 + a + 5 + b = 11 + a + b, अतः a + b = 7 या 16; b = 2 पर a = 5 और b = 6 पर a = 1 (इन b के साथ 16 असंभव)। अतः a + b = 7।"),
  Q(T(4), "If the four-digit number 8a1b is divisible by 88, what is the value of a × b?", "यदि चार अंकों की संख्या 8a1b, 88 से विभाज्य है, तो a × b का मान क्या है?", ["14", "16", "0", "21"], 0, () => single(fills("8a1b", 88).map((e) => e.a * e.b)),
    "For 8: a1b must be a multiple of 8. For 11: (8 + 1) − (a + b) = 9 − (a + b), so a + b = 9. Trying b = 0, 2, 4, 6, 8 with a = 9 − b: only a = 7, b = 2 gives 712 = 8 × 89. So a × b = 14 (8,712 = 88 × 99).", "8 के लिए: a1b, 8 का गुणज। 11 के लिए: (8 + 1) − (a + b) = 9 − (a + b), अतः a + b = 9। b = 0, 2, 4, 6, 8 और a = 9 − b आज़माने पर केवल a = 7, b = 2 से 712 = 8 × 89। अतः a × b = 14 (8,712 = 88 × 99)।"),
  Q(T(4), "If the four-digit number 7a6b is divisible by 66, what is the value of a + b?", "यदि चार अंकों की संख्या 7a6b, 66 से विभाज्य है, तो a + b का मान क्या है?", ["2", "13", "4", "11"], 0, () => single(fills("7a6b", 66).map((e) => e.a + e.b)),
    "66 = 2 × 3 × 11. For 11: (7 + 6) − (a + b) = 13 − (a + b), so a + b = 2 or 13. For 3: 13 + a + b must be a multiple of 3, which rules out 13 (sum 26) and keeps 2 (sum 15). With b even: (a, b) = (0, 2) or (2, 0). So a + b = 2.", "66 = 2 × 3 × 11। 11 के लिए: (7 + 6) − (a + b) = 13 − (a + b), अतः a + b = 2 या 13। 3 के लिए: 13 + a + b, 3 का गुणज, जो 13 (योग 26) को हटाता है और 2 (योग 15) रखता है। b सम: (a, b) = (0, 2) या (2, 0)। अतः a + b = 2।"),
  Q(T(4), "If the four-digit number a64b is divisible by 72, what is the largest such number?", "यदि चार अंकों की संख्या a64b, 72 से विभाज्य है, तो ऐसी सबसे बड़ी संख्या कौन-सी है?", ["9,648", "8,640", "9,640", "8,648"], 0, () => fmtN(Math.max(...fills("a64b", 72).map((e) => asNumber("a64b", e)))),
    "For 8: 64b is a multiple of 8 for b = 0 (640) or 8 (648). For 9: a + 6 + 4 + b is a multiple of 9: b = 0 needs a = 8, b = 8 needs a = 9. The numbers are 8,640 and 9,648; the larger is 9,648 = 72 × 134.", "8 के लिए: 64b, b = 0 (640) या 8 (648) पर 8 का गुणज। 9 के लिए: a + 6 + 4 + b, 9 का गुणज: b = 0 पर a = 8, b = 8 पर a = 9। संख्याएँ 8,640 और 9,648; बड़ी 9,648 = 72 × 134।"),
  Q(T(4), "If the four-digit number 3a2b is divisible by 44, what is the largest possible value of a + b?", "यदि चार अंकों की संख्या 3a2b, 44 से विभाज्य है, तो a + b का सबसे बड़ा संभव मान क्या है?", ["16", "5", "8", "12"], 0, () => Math.max(...fills("3a2b", 44).map((e) => e.a + e.b)),
    "For 4: 2b is a multiple of 4, so b = 0, 4 or 8. For 11: (3 + 2) − (a + b) = 5 − (a + b) must be 0 or −11, so a + b = 5 or 16. b = 0: a = 5; b = 4: a = 1; b = 8: a = 8 (sum 16). The largest a + b is 16 (3,828 = 44 × 87).", "4 के लिए: 2b, 4 का गुणज, अतः b = 0, 4 या 8। 11 के लिए: (3 + 2) − (a + b) = 5 − (a + b), 0 या −11, अतः a + b = 5 या 16। b = 0: a = 5; b = 4: a = 1; b = 8: a = 8 (योग 16)। सबसे बड़ा a + b = 16 (3,828 = 44 × 87)।"),
  Q(T(4), "If n is odd, (n − 1) × n × (n + 1) is always divisible by:", "यदि n विषम है, तो (n − 1) × n × (n + 1) सदैव किससे विभाज्य है?", ["24", "48", "16", "36"], 0, () => ["24", "48", "16", "36"].filter((d) => R(1, 60).filter((n) => n % 2).every((n) => ((n - 1) * n * (n + 1)) % num(d) === 0)).join(),
    "With n odd, n − 1 and n + 1 are consecutive even numbers, so one is a multiple of 4 and their product a multiple of 8. One of three consecutive numbers is a multiple of 3. So 8 × 3 = 24 always divides it. For n = 3 the value is 24, so 48, 16 and 36 do not always.", "n विषम हो तो n − 1 और n + 1 क्रमागत सम संख्याएँ, एक 4 का गुणज, अतः गुणनफल 8 का गुणज। तीन क्रमागत में एक 3 का गुणज। अतः 8 × 3 = 24 सदैव विभाजित करता है। n = 3 पर मान 24, अतः 48, 16 और 36 सदैव नहीं।"),
  Q(T(4), "A six-digit number is formed by writing a two-digit number three times (such as 474747). Such a number is always divisible by:", "एक दो अंकों की संख्या को तीन बार लिखकर छह अंकों की संख्या बनाई जाती है (जैसे 474747)। ऐसी संख्या सदैव किससे विभाज्य होती है?", ["7", "11", "17", "19"], 0, () => ["7", "11", "17", "19"].filter((d) => R(10, 99).every((ab) => (ab * 10101) % num(d) === 0)).join(),
    "ababab = ab × 10,101, and 10,101 = 3 × 7 × 13 × 37. So it is always divisible by 7. It need not be divisible by 11, 17 or 19 (474747 is not).", "ababab = ab × 10,101, और 10,101 = 3 × 7 × 13 × 37। अतः सदैव 7 से विभाज्य। 11, 17 या 19 से आवश्यक नहीं (474747 नहीं है)।"),
  Q(T(4), "If the five-digit number 2a3b4 is divisible by 72, what is the smallest such number?", "यदि पाँच अंकों की संख्या 2a3b4, 72 से विभाज्य है, तो ऐसी सबसे छोटी संख्या कौन-सी है?", ["20,304", "21,384", "25,344", "29,304"], 0, () => fmtN(Math.min(...fills("2a3b4", 72).map((e) => asNumber("2a3b4", e)))),
    "For 8: 3b4 is a multiple of 8 for b = 0 (304), 4 (344) or 8 (384). For 9: 2 + a + 3 + b + 4 = 9 + a + b, so a + b is 0, 9 or 18. b = 0 allows a = 0 or 9; b = 4, a = 5; b = 8, a = 1. The smallest number is 20,304 = 72 × 282.", "8 के लिए: 3b4, b = 0 (304), 4 (344) या 8 (384) पर 8 का गुणज। 9 के लिए: 2 + a + 3 + b + 4 = 9 + a + b, अतः a + b = 0, 9 या 18। b = 0 पर a = 0 या 9; b = 4 पर a = 5; b = 8 पर a = 1। सबसे छोटी संख्या 20,304 = 72 × 282।"),

  // ------------------------------------------------------------ MEDIUM #5
  Q(T(5), "If the four-digit number 9a03 is divisible by 13, what is the value of a?", "यदि चार अंकों की संख्या 9a03, 13 से विभाज्य है, तो a का मान क्या है?", ["5", "2", "8", "0"], 0, () => single(fills("9a03", 13).map((e) => e.a)),
    "9a03 = 9003 + 100a. 9003 = 13 × 692 + 7 and 100 leaves 9, so 7 + 9a must be a multiple of 13. a = 5 gives 52 = 13 × 4. So a = 5 (9503 = 13 × 731).", "9a03 = 9003 + 100a। 9003 = 13 × 692 + 7 और 100 का शेष 9, अतः 7 + 9a, 13 का गुणज हो। a = 5 पर 52 = 13 × 4। अतः a = 5 (9503 = 13 × 731)।"),
  Q(T(5), "If the four-digit number 4a29 is divisible by 13, what is the value of a?", "यदि चार अंकों की संख्या 4a29, 13 से विभाज्य है, तो a का मान क्या है?", ["3", "6", "9", "1"], 0, () => single(fills("4a29", 13).map((e) => e.a)),
    "4a29 = 4029 + 100a. 4029 = 13 × 309 + 12 and 100 leaves 9, so 12 + 9a must be a multiple of 13. a = 3 gives 39 = 13 × 3. So a = 3 (4329 = 13 × 333).", "4a29 = 4029 + 100a। 4029 = 13 × 309 + 12 और 100 का शेष 9, अतः 12 + 9a, 13 का गुणज हो। a = 3 पर 39 = 13 × 3। अतः a = 3 (4329 = 13 × 333)।"),
  Q(T(5), "The four-digit number 2a65 is divisible by 7. What is the largest possible value of the digit a?", "चार अंकों की संख्या 2a65, 7 से विभाज्य है। अंक a का सबसे बड़ा संभव मान क्या है?", ["7", "0", "9", "5"], 0, () => Math.max(...fills("2a65", 7).map((e) => e.a)),
    "2a65 = 2065 + 100a. 2065 = 7 × 295 exactly, so 100a must be a multiple of 7, i.e. a is 0 or 7. The largest is 7 (2765 = 7 × 395).", "2a65 = 2065 + 100a। 2065 = 7 × 295 ठीक-ठीक, अतः 100a, 7 का गुणज हो, यानी a = 0 या 7। सबसे बड़ा 7 (2765 = 7 × 395)।"),
  Q(T(5), "The four-digit number 3a78 is divisible by 7. What is the smallest possible value of the digit a?", "चार अंकों की संख्या 3a78, 7 से विभाज्य है। अंक a का सबसे छोटा संभव मान क्या है?", ["1", "8", "0", "4"], 0, () => Math.min(...fills("3a78", 7).map((e) => e.a)),
    "3a78 = 3078 + 100a. 3078 = 7 × 439 + 5 and 100 leaves 2, so 5 + 2a must be a multiple of 7: a = 1 (7) or a = 8 (21). The smallest is 1 (3178 = 7 × 454).", "3a78 = 3078 + 100a। 3078 = 7 × 439 + 5 और 100 का शेष 2, अतः 5 + 2a, 7 का गुणज हो: a = 1 (7) या a = 8 (21)। सबसे छोटा 1 (3178 = 7 × 454)।"),
  Q(T(5), "Which of 2,601, 3,601, 4,601 and 5,601 is divisible by 17?", "2,601, 3,601, 4,601 और 5,601 में से कौन-सी संख्या 17 से विभाज्य है?", ["2,601", "3,601", "4,601", "5,601"], 0, which(["2,601", "3,601", "4,601", "5,601"], (n) => n % 17 === 0),
    "2,601 = 51² = 17 × 153. The others are 1,000, 2,000 and 3,000 more, and 1,000 leaves 14 on division by 17, so they leave 14, 11 and 8: only 2,601 is a multiple.", "2,601 = 51² = 17 × 153। अन्य 1,000, 2,000 और 3,000 अधिक हैं, और 1,000 का 17 से शेष 14, अतः ये 14, 11 और 8 शेष छोड़ती हैं: केवल 2,601 गुणज है।"),
  Q(T(5), "What is the smallest number of 1s that a number written only with the digit 1 (11, 111, 1111, ...) must have to be divisible by 41?", "केवल अंक 1 से लिखी संख्या (11, 111, 1111, ...) में 41 से विभाज्य होने के लिए कम से कम कितने 1 होने चाहिए?", ["5", "3", "6", "8"], 0, () => R(1, 50).find((k) => BigInt("1".repeat(k)) % 41n === 0n),
    "11, 111 and 1,111 are not multiples of 41, but 11,111 = 41 × 271. So 5 ones.", "11, 111 और 1,111, 41 के गुणज नहीं, पर 11,111 = 41 × 271। अतः 5 इकाइयाँ।"),
  Q(T(5), "What is the largest five-digit number with all digits different that is divisible by 4?", "भिन्न अंकों वाली पाँच अंकों की वह सबसे बड़ी संख्या कौन-सी है जो 4 से विभाज्य हो?", ["98,764", "98,760", "98,756", "98,752"], 0, () => fmtN(R(10000, 99999).filter((n) => distinct(n) && n % 4 === 0).pop()),
    "Keep 9, 8, 7 in front; the last two digits must be a multiple of 4 from digits not used yet. The largest such pair after 987 is 64, giving 98,764. (98,756 and 98,752 are smaller, and 98,760 is smaller too.)", "आगे 9, 8, 7 रखें; अंतिम दो अंक अप्रयुक्त अंकों से 4 का गुणज हों। 987 के बाद सबसे बड़ा ऐसा जोड़ा 64, जिससे 98,764। (98,756, 98,752 और 98,760 छोटी हैं।)"),
  Q(T(5), "How many four-digit palindromes (numbers like 4,774 that read the same backwards) are divisible by 9?", "चार अंकों के कितने पैलिंड्रोम (4,774 जैसी संख्याएँ जो उलटा पढ़ने पर भी वही रहें) 9 से विभाज्य हैं?", ["10", "9", "11", "8"], 0, () => L.count(1000, 9999, (n) => String(n) === [...String(n)].reverse().join("") && n % 9 === 0),
    "A palindrome abba has digit sum 2(a + b), so it is divisible by 9 when a + b is 9 or 18. a + b = 9 with a from 1 to 9 gives 9 numbers; a + b = 18 gives 9999. Total 10.", "पैलिंड्रोम abba के अंकों का योग 2(a + b), अतः 9 से विभाज्य जब a + b = 9 या 18। a + b = 9 (a = 1 से 9) से 9 संख्याएँ; a + b = 18 से 9999। कुल 10।"),
  Q(T(5), "How many numbers from 1 to 1,000 are divisible by none of 2, 3, 5 and 7?", "1 से 1,000 तक कितनी संख्याएँ 2, 3, 5 और 7 में से किसी से भी विभाज्य नहीं हैं?", ["228", "200", "268", "234"], 0, () => L.count(1, 1000, (n) => n % 2 && n % 3 && n % 5 && n % 7),
    "By inclusion-exclusion the numbers divisible by at least one of 2, 3, 5, 7 come to 772 (500 + 333 + 200 + 142, minus the pairs, plus the triples, minus 4 for 210). So 1,000 − 772 = 228.", "समावेशन-अपवर्जन से 2, 3, 5, 7 में से कम से कम एक से विभाज्य संख्याएँ 772 (500 + 333 + 200 + 142, घटाएँ जोड़े, जोड़ें तिकड़ियाँ, घटाएँ 210 के 4)। अतः 1,000 − 772 = 228।"),
  Q(T(5), "For every natural number n, 4ⁿ − 1 is divisible by:", "हर प्राकृत संख्या n के लिए 4ⁿ − 1 किससे विभाज्य है?", ["3", "6", "5", "9"], 0, () => ["3", "6", "5", "9"].filter((d) => R(1, 12).every((n) => (4 ** n - 1) % num(d) === 0)).join(),
    "aⁿ − 1 is always divisible by a − 1 = 3. For n = 1 the value is 3 itself, so 6, 5 and 9 do not always divide it.", "aⁿ − 1 सदैव a − 1 = 3 से विभाज्य है। n = 1 पर मान स्वयं 3, अतः 6, 5 और 9 सदैव नहीं।"),
  Q(T(5), "For every odd natural number n, n² + 3 is divisible by:", "हर विषम प्राकृत संख्या n के लिए n² + 3 किससे विभाज्य है?", ["4", "8", "3", "6"], 0, () => ["4", "8", "3", "6"].filter((d) => R(1, 60).filter((n) => n % 2).every((n) => (n * n + 3) % num(d) === 0)).join(),
    "An odd square leaves 1 on division by 8, so n² + 3 leaves 4: it is a multiple of 4 but not of 8. For n = 1 the value is 4, so 3 and 6 do not always divide it.", "विषम वर्ग का 8 से शेष 1, अतः n² + 3 का शेष 4: यह 4 का गुणज है, 8 का नहीं। n = 1 पर मान 4, अतः 3 और 6 सदैव नहीं।"),
  Q(T(5), "By which of the following is 5²⁵ − 5²⁴ divisible?", "5²⁵ − 5²⁴ निम्नलिखित में से किससे विभाज्य है?", ["4", "3", "6", "7"], 0, () => ["4", "3", "6", "7"].filter((d) => (5n ** 25n - 5n ** 24n) % BigInt(num(d)) === 0n).join(),
    "5²⁵ − 5²⁴ = 5²⁴(5 − 1) = 4 × 5²⁴. It is divisible by 4; its only prime factors are 2 and 5, so not by 3, 6 or 7.", "5²⁵ − 5²⁴ = 5²⁴(5 − 1) = 4 × 5²⁴। यह 4 से विभाज्य है; इसके अभाज्य गुणनखंड केवल 2 और 5, अतः 3, 6 या 7 से नहीं।"),
  Q(T(5), "If the four-digit number 9a8b is divisible by 36, how many pairs of digits (a, b) are possible?", "यदि चार अंकों की संख्या 9a8b, 36 से विभाज्य है, तो अंकों (a, b) के कितने जोड़े संभव हैं?", ["3", "2", "4", "1"], 0, () => fills("9a8b", 36).length,
    "For 4: 8b is a multiple of 4, so b = 0, 4 or 8. For 9: 9 + a + 8 + b = 17 + a + b, so a + b = 1 or 10. b = 0: a = 1; b = 4: a = 6; b = 8: a = 2. So 3 pairs.", "4 के लिए: 8b, 4 का गुणज, अतः b = 0, 4 या 8। 9 के लिए: 9 + a + 8 + b = 17 + a + b, अतः a + b = 1 या 10। b = 0: a = 1; b = 4: a = 6; b = 8: a = 2। अतः 3 जोड़े।"),
  Q(T(5), "For how many pairs of digits (a, b) is the four-digit number 6a2b divisible by 24?", "अंकों (a, b) के कितने जोड़ों के लिए चार अंकों की संख्या 6a2b, 24 से विभाज्य है?", ["5", "4", "6", "3"], 0, () => fills("6a2b", 24).length,
    "For 8: a2b must be a multiple of 8. For 3: 6 + a + 2 + b = 8 + a + b, a multiple of 3. Checking b even and a from 0 to 9: (0, 4), (1, 0), (5, 8), (6, 4), (7, 0). Five pairs.", "8 के लिए: a2b, 8 का गुणज। 3 के लिए: 6 + a + 2 + b = 8 + a + b, 3 का गुणज। b सम और a = 0 से 9 जाँचने पर: (0, 4), (1, 0), (5, 8), (6, 4), (7, 0)। पाँच जोड़े।"),
  Q(T(5), "If the four-digit number a2b8 is divisible by 72, what is the largest possible value of a + b?", "यदि चार अंकों की संख्या a2b8, 72 से विभाज्य है, तो a + b का सबसे बड़ा संभव मान क्या है?", ["17", "8", "13", "16"], 0, () => Math.max(...fills("a2b8", 72).map((e) => e.a + e.b)),
    "For 9: a + 2 + b + 8 = 10 + a + b, so a + b = 8 or 17. For 8: 2b8 is a multiple of 8 for b = 0, 4 or 8. a + b = 17 needs b = 8, a = 9: 9,288 = 72 × 129. So the largest a + b is 17.", "9 के लिए: a + 2 + b + 8 = 10 + a + b, अतः a + b = 8 या 17। 8 के लिए: 2b8, b = 0, 4 या 8 पर 8 का गुणज। a + b = 17 के लिए b = 8, a = 9: 9,288 = 72 × 129। अतः सबसे बड़ा a + b = 17।"),
  Q(T(5), "If the four-digit number 3a5b is divisible by 45, what is the largest such number?", "यदि चार अंकों की संख्या 3a5b, 45 से विभाज्य है, तो ऐसी सबसे बड़ी संख्या कौन-सी है?", ["3,555", "3,150", "3,950", "3,545"], 0, () => fmtN(Math.max(...fills("3a5b", 45).map((e) => asNumber("3a5b", e)))),
    "For 5: b = 0 or 5. For 9: 3 + a + 5 + b = 8 + a + b. b = 0 needs a = 1 (3,150); b = 5 needs a = 5 (3,555). The larger is 3,555 = 45 × 79.", "5 के लिए: b = 0 या 5। 9 के लिए: 3 + a + 5 + b = 8 + a + b। b = 0 पर a = 1 (3,150); b = 5 पर a = 5 (3,555)। बड़ी 3,555 = 45 × 79।"),
  Q(T(5), "How many three-digit numbers are divisible by 13?", "तीन अंकों की कितनी संख्याएँ 13 से विभाज्य हैं?", ["69", "70", "68", "76"], 0, () => L.count(100, 999, (n) => n % 13 === 0),
    "They run from 104 = 13 × 8 to 988 = 13 × 76: 76 − 8 + 1 = 69 numbers.", "ये 104 = 13 × 8 से 988 = 13 × 76 तक हैं: 76 − 8 + 1 = 69 संख्याएँ।"),
  Q(T(5), "How many multiples of 7 between 1,000 and 2,000 end in the digit 3?", "1,000 और 2,000 के बीच 7 के कितने गुणज अंक 3 पर समाप्त होते हैं?", ["14", "15", "13", "143"], 0, () => L.count(1000, 2000, (n) => n % 7 === 0 && n % 10 === 3),
    "7k ends in 3 exactly when k ends in 9 (7 × 9 = 63). Multiples of 7 in the range are 7 × 143 to 7 × 285; the k ending in 9 are 149, 159, ..., 279: 14 values.", "7k का अंतिम अंक 3 तभी जब k का अंतिम अंक 9 (7 × 9 = 63)। सीमा में 7 के गुणज 7 × 143 से 7 × 285; 9 पर समाप्त k: 149, 159, ..., 279: 14 मान।"),
  Q(T(5), "If the four-digit number 9a4b is divisible by 33, what is the value of a + b?", "यदि चार अंकों की संख्या 9a4b, 33 से विभाज्य है, तो a + b का मान क्या है?", ["2", "13", "5", "11"], 0, () => single(fills("9a4b", 33).map((e) => e.a + e.b)),
    "For 11: (9 + 4) − (a + b) = 13 − (a + b), so a + b = 2 or 13. For 3: 13 + a + b must be a multiple of 3, which keeps a + b = 2 (sum 15) and rules out 13 (sum 26). So a + b = 2.", "11 के लिए: (9 + 4) − (a + b) = 13 − (a + b), अतः a + b = 2 या 13। 3 के लिए: 13 + a + b, 3 का गुणज, जो a + b = 2 (योग 15) रखता है और 13 (योग 26) हटाता है। अतः a + b = 2।"),
  Q(T(5), "Which of 5,742, 6,743, 7,824 and 8,715 is divisible by 99?", "5,742, 6,743, 7,824 और 8,715 में से कौन-सी संख्या 99 से विभाज्य है?", ["5,742", "6,743", "7,824", "8,715"], 0, which(["5,742", "6,743", "7,824", "8,715"], (n) => n % 99 === 0),
    "100 leaves 1 on division by 99, so a number leaves the same as the sum of its two-digit blocks from the right: 57 + 42 = 99, 67 + 43 = 110, 78 + 24 = 102, 87 + 15 = 102. Only 5,742 gives a multiple of 99 (5,742 = 99 × 58).", "100 का 99 से शेष 1, अतः संख्या का शेष दाईं ओर से दो-दो अंकों के खंडों के योग जैसा: 57 + 42 = 99, 67 + 43 = 110, 78 + 24 = 102, 87 + 15 = 102। केवल 5,742 से 99 का गुणज (5,742 = 99 × 58)।"),

  // ------------------------------------------------------------ MEDIUM #6
  Q(T(6), "How many numbers from 1 to 1,000 are divisible by 4 but not by 8?", "1 से 1,000 तक कितनी संख्याएँ 4 से विभाज्य हैं पर 8 से नहीं?", ["125", "250", "124", "375"], 0, () => L.count(1, 1000, (n) => n % 4 === 0 && n % 8 !== 0),
    "Multiples of 4: 250. Multiples of 8, which are all multiples of 4: 125. So 250 − 125 = 125.", "4 के गुणज: 250। 8 के गुणज, जो सभी 4 के भी गुणज हैं: 125। अतः 250 − 125 = 125।"),
  Q(T(6), "What is the smallest four-digit number divisible by each of 3, 5 and 7?", "3, 5 और 7 में से प्रत्येक से विभाज्य चार अंकों की सबसे छोटी संख्या कौन-सी है?", ["1,050", "1,005", "1,035", "1,105"], 0, () => fmtN(R(1000, 9999).find((n) => n % 105 === 0)),
    "It must be a multiple of 3 × 5 × 7 = 105. 1,000 = 105 × 9 + 55, so the next multiple is 105 × 10 = 1,050.", "यह 3 × 5 × 7 = 105 का गुणज हो। 1,000 = 105 × 9 + 55, अतः अगला गुणज 105 × 10 = 1,050।"),
  Q(T(6), "What is the smallest four-digit number divisible by 99?", "99 से विभाज्य चार अंकों की सबसे छोटी संख्या कौन-सी है?", ["1,089", "1,099", "1,001", "1,098"], 0, () => fmtN(R(1000, 9999).find((n) => n % 99 === 0)),
    "1,000 = 99 × 10 + 10, so the next multiple of 99 is 99 × 11 = 1,089. (Check: 10 + 89 = 99.)", "1,000 = 99 × 10 + 10, अतः 99 का अगला गुणज 99 × 11 = 1,089। (जाँच: 10 + 89 = 99।)"),
  Q(T(6), "What is the largest four-digit number divisible by each of 2, 3, 4, 5 and 6?", "2, 3, 4, 5 और 6 में से प्रत्येक से विभाज्य चार अंकों की सबसे बड़ी संख्या कौन-सी है?", ["9,960", "9,990", "9,900", "9,840"], 0, () => fmtN(R(1000, 9999).filter((n) => n % L.lcm(2, 3, 4, 5, 6) === 0).pop()),
    "LCM(2, 3, 4, 5, 6) = 60. 9,999 = 60 × 166 + 39, so the largest multiple is 9,999 − 39 = 9,960.", "LCM(2, 3, 4, 5, 6) = 60। 9,999 = 60 × 166 + 39, अतः सबसे बड़ा गुणज 9,999 − 39 = 9,960।"),
  Q(T(6), "What is the smallest three-digit number that is divisible by 11 and has a digit sum of 11?", "तीन अंकों की वह सबसे छोटी संख्या कौन-सी है जो 11 से विभाज्य हो और जिसके अंकों का योग 11 हो?", ["209", "308", "418", "506"], 0, () => R(100, 999).find((n) => n % 11 === 0 && L.digitSum(n) === 11),
    "Go through the multiples of 11 from 110: digit sums 2, 4, 6, 8, 10 (110 to 154), then 165 → 12, 176 → 14, 187 → 16, 198 → 18, 209 → 11. So 209 = 11 × 19.", "110 से 11 के गुणज देखें: अंकों के योग 2, 4, 6, 8, 10 (110 से 154), फिर 165 → 12, 176 → 14, 187 → 16, 198 → 18, 209 → 11। अतः 209 = 11 × 19।"),
  Q(T(6), "How many four-digit numbers have all their digits even and are divisible by 5?", "चार अंकों की कितनी संख्याओं के सभी अंक सम हैं और वे 5 से विभाज्य हैं?", ["100", "125", "80", "500"], 0, () => L.count(1000, 9999, (n) => [...String(n)].every((c) => "02468".includes(c)) && n % 5 === 0),
    "Divisible by 5 with an even last digit means the last digit is 0. The first digit is 2, 4, 6 or 8 (4 ways) and the middle two any even digit (5 × 5). So 4 × 25 = 100.", "5 से विभाज्य और अंतिम अंक सम, अतः अंतिम अंक 0। पहला अंक 2, 4, 6 या 8 (4 तरह) और बीच के दो कोई भी सम अंक (5 × 5)। अतः 4 × 25 = 100।"),
  Q(T(6), "How many three-digit numbers with all three digits odd are divisible by 4?", "तीनों अंक विषम वाली तीन अंकों की कितनी संख्याएँ 4 से विभाज्य हैं?", ["0", "25", "20", "5"], 0, () => L.count(100, 999, (n) => [...String(n)].every((c) => "13579".includes(c)) && n % 4 === 0),
    "A number whose last digit is odd is itself odd, and an odd number is never divisible by 4 (or even by 2). So there are none: 0.", "जिस संख्या का अंतिम अंक विषम हो वह स्वयं विषम है, और विषम संख्या कभी 4 (या 2) से विभाज्य नहीं। अतः कोई नहीं: 0।"),
  Q(T(6), "In a three-digit number the middle digit equals the sum of the other two (as in 253). Such a number is always divisible by:", "तीन अंकों की एक संख्या में बीच का अंक बाकी दोनों के योग के बराबर है (जैसे 253)। ऐसी संख्या सदैव किससे विभाज्य होती है?", ["11", "7", "13", "9"], 0, () => ["11", "7", "13", "9"].filter((d) => R(100, 999).filter((n) => { const [a, b, c] = [...String(n)].map(Number); return b === a + c; }).every((n) => n % num(d) === 0)).join(),
    "With b = a + c the alternate-digit difference is (a + c) − b = 0, so the number is divisible by 11 (253 = 11 × 23). 253 is not divisible by 7, 13 or 9.", "b = a + c होने पर एकांतर अंकों का अंतर (a + c) − b = 0, अतः संख्या 11 से विभाज्य (253 = 11 × 23)। 253, 7, 13 या 9 से विभाज्य नहीं।"),
  Q(T(6), "A three-digit number abc is added to bca and cab (its digits moved round, as in 123 + 231 + 312). The sum is always divisible by:", "तीन अंकों की संख्या abc में bca और cab (अंक चक्रीय क्रम में, जैसे 123 + 231 + 312) जोड़े जाते हैं। योग सदैव किससे विभाज्य होता है?", ["37", "17", "13", "23"], 0, () => ["37", "17", "13", "23"].filter((d) => R(100, 999).every((n) => { const t = String(n); return (Number(t) + Number(t[1] + t[2] + t[0]) + Number(t[2] + t[0] + t[1])) % num(d) === 0; })).join(),
    "Each digit appears once in each place, so the sum is 111(a + b + c) = 3 × 37 × (a + b + c), always a multiple of 37. For 123 the sum is 666 = 37 × 18, not divisible by 17, 13 or 23.", "हर अंक हर स्थान पर एक बार आता है, अतः योग = 111(a + b + c) = 3 × 37 × (a + b + c), सदैव 37 का गुणज। 123 के लिए योग 666 = 37 × 18, जो 17, 13 या 23 से विभाज्य नहीं।"),
  Q(T(6), "Both a and b are multiples of 7. Which of the following is then always a multiple of 7?", "a और b दोनों 7 के गुणज हैं। तब निम्नलिखित में से कौन सदैव 7 का गुणज है?", ["3a − 2b", "a + 1", "ab + 1", "a + b + 7k + 1"], 0, () => {
      const pairs = [[7, 14], [21, 35], [49, 0]];
      const f = { "3a − 2b": (a, b) => 3 * a - 2 * b, "a + 1": (a) => a + 1, "ab + 1": (a, b) => a * b + 1, "a + b + 7k + 1": (a, b) => a + b + 7 * 3 + 1 };
      return Object.keys(f).filter((k) => pairs.every(([a, b]) => f[k](a, b) % 7 === 0)).join();
    },
    "With a = 7m and b = 7n, 3a − 2b = 7(3m − 2n), a multiple of 7. Each of the others is a multiple of 7 plus 1, so never a multiple of 7.", "a = 7m और b = 7n होने पर 3a − 2b = 7(3m − 2n), 7 का गुणज। बाकी हर एक 7 का गुणज + 1 है, अतः कभी 7 का गुणज नहीं।"),
  Q(T(6), "How many numbers from 1 to 600 are divisible by exactly one of 3 and 7?", "1 से 600 तक कितनी संख्याएँ 3 और 7 में से ठीक एक से विभाज्य हैं?", ["229", "257", "28", "200"], 0, () => L.count(1, 600, (n) => (n % 3 === 0) !== (n % 7 === 0)),
    "Multiples of 3: 200; of 7: 85; of 21: 28. Exactly one: (200 − 28) + (85 − 28) = 172 + 57 = 229.", "3 के गुणज: 200; 7 के: 85; 21 के: 28। ठीक एक: (200 − 28) + (85 − 28) = 172 + 57 = 229।"),
  Q(T(6), "How many three-digit numbers are divisible by both 3 and 13?", "तीन अंकों की कितनी संख्याएँ 3 और 13 दोनों से विभाज्य हैं?", ["23", "24", "22", "69"], 0, () => L.count(100, 999, (n) => n % 39 === 0),
    "Divisible by both means divisible by 39. They run from 117 = 39 × 3 to 975 = 39 × 25: 25 − 3 + 1 = 23.", "दोनों से विभाज्य यानी 39 से विभाज्य। ये 117 = 39 × 3 से 975 = 39 × 25 तक: 25 − 3 + 1 = 23।"),
  Q(T(6), "How many two-digit numbers are divisible by the product of their own digits?", "दो अंकों की कितनी संख्याएँ अपने ही अंकों के गुणनफल से विभाज्य हैं?", ["5", "4", "6", "3"], 0, () => L.count(10, 99, (n) => { const p = [...String(n)].reduce((a, d) => a * Number(d), 1); return p > 0 && n % p === 0; }),
    "A 0 digit makes the product 0, so those are out. Checking the rest: 11 (1), 12 (2), 15 (5), 24 (8) and 36 (18) work. That is 5 numbers.", "0 वाला अंक गुणनफल 0 कर देता है, वे बाहर। बाकी जाँचने पर: 11 (1), 12 (2), 15 (5), 24 (8) और 36 (18)। कुल 5 संख्याएँ।"),
  Q(T(6), "If the four-digit number 7a2b is divisible by 99, what is the value of a + b?", "यदि चार अंकों की संख्या 7a2b, 99 से विभाज्य है, तो a + b का मान क्या है?", ["9", "18", "7", "0"], 0, () => single(fills("7a2b", 99).map((e) => e.a + e.b)),
    "For 99 add the two-digit blocks: 7a + 2b = (70 + a) + (20 + b) = 90 + a + b must be a multiple of 99, so a + b = 9. (Every such pair works, e.g. 7,029 = 99 × 71.)", "99 के लिए दो-दो अंकों के खंड जोड़ें: 7a + 2b = (70 + a) + (20 + b) = 90 + a + b, 99 का गुणज, अतः a + b = 9। (हर ऐसा जोड़ा चलता है, जैसे 7,029 = 99 × 71।)"),
  Q(T(6), "If the five-digit number 4a1b6 is divisible by 88, what is the value of a + b?", "यदि पाँच अंकों की संख्या 4a1b6, 88 से विभाज्य है, तो a + b का मान क्या है?", ["11", "13", "7", "9"], 0, () => single(fills("4a1b6", 88).map((e) => e.a + e.b)),
    "For 11: (4 + 1 + 6) − (a + b) = 11 − (a + b), so a + b = 0 or 11. For 8: 1b6 is a multiple of 8 for b = 3 (136) or b = 7 (176), so a + b = 0 is impossible. With b = 3, a = 8; with b = 7, a = 4. Either way a + b = 11.", "11 के लिए: (4 + 1 + 6) − (a + b) = 11 − (a + b), अतः a + b = 0 या 11। 8 के लिए: 1b6, b = 3 (136) या b = 7 (176) पर 8 का गुणज, अतः a + b = 0 असंभव। b = 3 पर a = 8; b = 7 पर a = 4। हर हाल में a + b = 11।"),
  Q(T(6), "For how many pairs of digits (a, b) is the four-digit number 1a8b divisible by 44?", "अंकों (a, b) के कितने जोड़ों के लिए चार अंकों की संख्या 1a8b, 44 से विभाज्य है?", ["3", "2", "4", "5"], 0, () => fills("1a8b", 44).length,
    "For 4: 8b is a multiple of 4, so b = 0, 4 or 8. For 11: (1 + 8) − (a + b) = 9 − (a + b), so a + b = 9. That gives (9, 0), (5, 4) and (1, 8): 3 pairs.", "4 के लिए: 8b, 4 का गुणज, अतः b = 0, 4 या 8। 11 के लिए: (1 + 8) − (a + b) = 9 − (a + b), अतः a + b = 9। इससे (9, 0), (5, 4) और (1, 8): 3 जोड़े।"),
  Q(T(6), "The four-digit number a5b4 is divisible by 72. What is the smallest such number?", "चार अंकों की संख्या a5b4, 72 से विभाज्य है। ऐसी सबसे छोटी संख्या कौन-सी है?", ["1,584", "5,544", "9,504", "1,504"], 0, () => fmtN(Math.min(...fills("a5b4", 72).map((e) => asNumber("a5b4", e)))),
    "For 8: 5b4 is a multiple of 8 for b = 0, 4 or 8. For 9: a + 5 + b + 4 = 9 + a + b, so a + b = 9: (9, 0), (5, 4), (1, 8). The numbers are 9,504, 5,544 and 1,584; the smallest is 1,584 = 72 × 22.", "8 के लिए: 5b4, b = 0, 4 या 8 पर 8 का गुणज। 9 के लिए: a + 5 + b + 4 = 9 + a + b, अतः a + b = 9: (9, 0), (5, 4), (1, 8)। संख्याएँ 9,504, 5,544 और 1,584; सबसे छोटी 1,584 = 72 × 22।"),
  Q(T(6), "The four-digit number 2a5b is divisible by 36. What is the smallest such number?", "चार अंकों की संख्या 2a5b, 36 से विभाज्य है। ऐसी सबसे छोटी संख्या कौन-सी है?", ["2,052", "2,556", "2,952", "2,250"], 0, () => fmtN(Math.min(...fills("2a5b", 36).map((e) => asNumber("2a5b", e)))),
    "For 4: 5b is a multiple of 4, so b = 2 or 6. For 9: 2 + a + 5 + b = 7 + a + b. b = 2: a = 0 or 9; b = 6: a = 5. The numbers are 2,052, 2,952 and 2,556; the smallest is 2,052 = 36 × 57.", "4 के लिए: 5b, 4 का गुणज, अतः b = 2 या 6। 9 के लिए: 2 + a + 5 + b = 7 + a + b। b = 2: a = 0 या 9; b = 6: a = 5। संख्याएँ 2,052, 2,952 और 2,556; सबसे छोटी 2,052 = 36 × 57।"),
  Q(T(6), "The five-digit number 34a5b is divisible by 36. What is the largest such number?", "पाँच अंकों की संख्या 34a5b, 36 से विभाज्य है। ऐसी सबसे बड़ी संख्या कौन-सी है?", ["34,956", "34,452", "34,056", "34,952"], 0, () => fmtN(Math.max(...fills("34a5b", 36).map((e) => asNumber("34a5b", e)))),
    "For 4: 5b is a multiple of 4, so b = 2 or 6. For 9: 3 + 4 + a + 5 + b = 12 + a + b. b = 2: a = 4; b = 6: a = 0 or 9. The numbers are 34,452, 34,056 and 34,956; the largest is 34,956 = 36 × 971.", "4 के लिए: 5b, 4 का गुणज, अतः b = 2 या 6। 9 के लिए: 3 + 4 + a + 5 + b = 12 + a + b। b = 2: a = 4; b = 6: a = 0 या 9। संख्याएँ 34,452, 34,056 और 34,956; सबसे बड़ी 34,956 = 36 × 971।"),
  Q(T(6), "If the six-digit number 15a2b6 is divisible by 72, what is the largest possible value of a + b?", "यदि छह अंकों की संख्या 15a2b6, 72 से विभाज्य है, तो a + b का सबसे बड़ा संभव मान क्या है?", ["13", "4", "9", "17"], 0, () => Math.max(...fills("15a2b6", 72).map((e) => e.a + e.b)),
    "For 8: 2b6 is a multiple of 8 for b = 1 (216), 5 (256) or 9 (296). For 9: 1 + 5 + a + 2 + b + 6 = 14 + a + b, so a + b = 4 or 13. b = 1: a = 3; b = 5: a = 8; b = 9: a = 4. The sums are 4, 13 and 13; the largest is 13.", "8 के लिए: 2b6, b = 1 (216), 5 (256) या 9 (296) पर 8 का गुणज। 9 के लिए: 1 + 5 + a + 2 + b + 6 = 14 + a + b, अतः a + b = 4 या 13। b = 1: a = 3; b = 5: a = 8; b = 9: a = 4। योग 4, 13 और 13; सबसे बड़ा 13।"),
];
module.exports = list.map(fmt);
